import{_ as t,o as s,c as i,a2 as o}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Permissions and security: define every trust boundary","description":"Configure server secrets, browser sessions, repository access, webhooks, and MCP network boundaries, then verify them with a production checklist.","frontmatter":{"page_id":"configuration-security","title":"Permissions and security: define every trust boundary","description":"Configure server secrets, browser sessions, repository access, webhooks, and MCP network boundaries, then verify them with a production checklist."},"headers":[],"relativePath":"en/configuration/security.md","filePath":"en/configuration/security.md","lastUpdated":1786290726000}'),r={name:"en/configuration/security.md"};function a(n,e,d,c,l,h){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="permissions-and-security-define-every-trust-boundary" tabindex="-1">Permissions and security: define every trust boundary <a class="header-anchor" href="#permissions-and-security-define-every-trust-boundary" aria-label="Permalink to &quot;Permissions and security: define every trust boundary&quot;">​</a></h1><p>Ershu handles source repositories, login state, and model credentials. Secure deployment is not a single switch. Define the trust boundary for browsers, repositories, webhooks, MCP, and administrator actions separately.</p><h2 id="protect-four-kinds-of-server-material" tabindex="-1">Protect four kinds of server material <a class="header-anchor" href="#protect-four-kinds-of-server-material" aria-label="Permalink to &quot;Protect four kinds of server material&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Purpose</th><th>Effect of rotation</th></tr></thead><tbody><tr><td><code>SECRET_KEY</code></td><td>Signs access and CSRF tokens</td><td>Existing access and CSRF tokens become invalid</td></tr><tr><td><code>ENCRYPTION_KEY</code></td><td>Encrypts model keys, repository credentials, and login material stored in the database</td><td>Existing ciphertext may become unreadable</td></tr><tr><td><code>MCP_KEY_PEPPER</code></td><td>Adds server-side material outside the database to MCP key digests</td><td>Every existing MCP key becomes invalid</td></tr><tr><td><code>OPAQUE_SERVER_SETUP</code></td><td>Maintains the server identity for password registration and login</td><td>Existing password records may no longer authenticate</td></tr></tbody></table><p>The first three values must be distinct, at least 32 characters long, and different from the weak values listed in source. Inject them through the deployment platform&#39;s secret manager; never store them in a repository, image, or public log.</p><p>In development, the API can create <code>OPAQUE_SERVER_SETUP</code> during its first startup and store it encrypted in the database. Production requires an explicit, stable value. Current startup validation checks its presence and basic strength; actual authentication must also decode it as valid OPAQUE server material. An arbitrary long string is not sufficient.</p><h2 id="protect-browser-sessions" tabindex="-1">Protect browser sessions <a class="header-anchor" href="#protect-browser-sessions" aria-label="Permalink to &quot;Protect browser sessions&quot;">​</a></h2><p>A production environment needs at least:</p><div class="language-dotenv vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ENVIRONMENT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">production</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_COOKIE_SECURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">true</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_COOKIE_SAMESITE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lax</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">CORS_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://ershu.example.org&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Replace the example domain with the real frontend origin. Browser protection has three layers:</p><ol><li>In production, requests under <code>/api/</code> and <code>/mcp</code> must appear as HTTPS or receive a 400 response.</li><li>A write request authenticated by session Cookie must include both a valid <code>X-Ershu-CSRF</code> header and CSRF Cookie. When the request has <code>Origin</code> or <code>Referer</code>, that origin must also be the current site or an entry in <code>CORS_ORIGINS</code>; otherwise the API returns 403.</li><li>A request with <code>Authorization: Bearer ...</code> does not authenticate through browser Cookies, so it bypasses the CSRF check but still passes through token authentication and endpoint authorization.</li></ol><p><code>SESSION_COOKIE_SAMESITE=none</code> is normally appropriate only when a deployment intentionally needs cross-site Cookies. It still requires secure Cookies and a precise origin list. Do not use broad origins to hide a proxy or domain error.</p><p>If a reverse proxy terminates HTTPS, put only the actual proxy addresses in <code>FORWARDED_ALLOW_IPS</code>. The API decides whether a request is secure from its scheme; untrusted forwarded headers or a missing forwarded scheme can cause incorrect acceptance or rejection.</p><h2 id="restrict-remote-git-urls" tabindex="-1">Restrict remote Git URLs <a class="header-anchor" href="#restrict-remote-git-urls" aria-label="Permalink to &quot;Restrict remote Git URLs&quot;">​</a></h2><p>By default, repository URLs may use only:</p><ul><li><code>https://</code>;</li><li><code>ssh://</code>;</li><li>SCP-like SSH syntax such as <code>user@host:path</code>.</li></ul><p><code>http://</code> and <code>git://</code> require <code>ALLOW_INSECURE_GIT_URLS=true</code>. <code>file://</code> requires <code>ALLOW_FILE_GIT_URLS=true</code>. Both switches default to false and should remain false in production unless the risk has been explicitly evaluated and isolated.</p><p><code>GIT_ALLOWED_HOSTS</code> defines the remote host boundary:</p><ul><li>with an empty list, the host must still resolve, and loopback, private, link-local, multicast, reserved, and unspecified addresses are rejected by default;</li><li>with a non-empty list, a host that does not match is rejected immediately;</li><li>an exact or wildcard allowlist match may resolve to a private address, but loopback, link-local, and the other blocked classes remain rejected;</li><li><code>*.example.org</code> matches subdomains but not <code>example.org</code> itself.</li></ul><p>List the actual Git hosts in production and avoid <code>*</code>. Host validation runs before later clones and fetches; changing the list does not reinspect cache content that already exists.</p><h2 id="restrict-local-repository-paths" tabindex="-1">Restrict local repository paths <a class="header-anchor" href="#restrict-local-repository-paths" aria-label="Permalink to &quot;Restrict local repository paths&quot;">​</a></h2><p>Core trusts a local repository workspace only when at least one condition is true:</p><ul><li>it is inside the cache managed by <code>REPOSITORY_STORAGE_PATH</code>;</li><li>it is the same as, or below, an entry in <code>TRUSTED_LOCAL_PATHS</code>;</li><li>the directory itself contains <code>.git</code>.</li></ul><p><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS=true</code> is a development fallback. It applies only when there is no trusted-path list and the environment is not production. Production validation rejects it. Administrators should still add only the paths that need analysis: “trusted” means readable, not intrinsically safe.</p><h2 id="assign-repository-credentials" tabindex="-1">Assign repository credentials <a class="header-anchor" href="#assign-repository-credentials" aria-label="Permalink to &quot;Assign repository credentials&quot;">​</a></h2><p>A repository can use a dedicated token, an SSH private key, or a credential that names a process environment variable. Core prefers the repository-specific credential. Only when there is no dedicated token does a GitHub or GitLab repository fall back to global <code>GITHUB_TOKEN</code> or <code>GITLAB_TOKEN</code>.</p><p>Tokens are exposed only to an individual Git subprocess, and temporary credential files are removed after the command. Database-stored tokens and SSH keys depend on <code>ENCRYPTION_KEY</code> for decryption. Still grant the minimum permission required: repository read access, without write or organization-management permission.</p><h2 id="sign-repository-webhooks-correctly" tabindex="-1">Sign repository webhooks correctly <a class="header-anchor" href="#sign-repository-webhooks-correctly" aria-label="Permalink to &quot;Sign repository webhooks correctly&quot;">​</a></h2><p>Before enabling a webhook, a project manager must set a secret with at least 16 characters. Every request uses three headers:</p><ul><li><code>X-Ershu-Webhook-Timestamp</code>: no more than five minutes away from server time;</li><li><code>X-Ershu-Webhook-Nonce</code>: single-use, at most 255 characters, with no colon or newline;</li><li><code>X-Ershu-Webhook-Signature</code>: the hexadecimal HMAC-SHA256 digest made with the webhook secret.</li></ul><p>Build the signed bytes in this exact order: timestamp, one NUL byte, nonce, one NUL byte, and the unchanged raw request body. An older body-only signature will fail. The API stores used nonces in the database and rejects reuse inside the validity window.</p><h2 id="tighten-the-mcp-network-boundary" tabindex="-1">Tighten the MCP network boundary <a class="header-anchor" href="#tighten-the-mcp-network-boundary" aria-label="Permalink to &quot;Tighten the MCP network boundary&quot;">​</a></h2><p>In production, MCP also checks that:</p><ul><li><code>MCP_BUILD_COMMIT</code> is the exact 40-character hexadecimal source commit;</li><li>the process can read installed <code>ershu-mcp</code> package metadata;</li><li><code>MCP_ENABLE_DNS_REBINDING_PROTECTION=true</code>;</li><li>neither <code>MCP_ALLOWED_HOSTS</code> nor <code>MCP_ALLOWED_ORIGINS</code> is empty.</li></ul><p>These settings protect the network entry point. Project and tool permissions still come from the MCP key scope, user identity, and project membership. An allowed network origin is not a substitute for endpoint authorization.</p><h2 id="verifiable-production-checklist" tabindex="-1">Verifiable production checklist <a class="header-anchor" href="#verifiable-production-checklist" aria-label="Permalink to &quot;Verifiable production checklist&quot;">​</a></h2><ul><li>Use four independent, stable pieces of server material, and confirm in a backup-recovery exercise that old ciphertext remains decryptable.</li><li>Request a protected API over HTTPS. The HTTP request should be rejected, while the HTTPS response should include HSTS.</li><li>Sign in from an allowed frontend origin and complete one write. Remove the CSRF header and confirm that the same write returns 403.</li><li>Add or refresh a repository whose host is outside <code>GIT_ALLOWED_HOSTS</code>; it should be rejected before Git runs.</li><li>Send the same webhook timestamp, nonce, body, and signature twice; the second request should be rejected.</li><li>Call the administrator system-settings endpoint as a regular user and expect 403; only an administrator should read it.</li><li>Before rotating <code>MCP_KEY_PEPPER</code>, plan to issue replacement MCP keys because old keys will stop working.</li></ul><p>These are acceptance conditions, not a claim that this page has executed the tests in your environment.</p><h2 id="source-locations" tabindex="-1">Source locations <a class="header-anchor" href="#source-locations" aria-label="Permalink to &quot;Source locations&quot;">​</a></h2><ul><li><code>core/src/ershu/core/config.py</code>: secret strength, distinctness, and the production local-path check.</li><li><code>core/src/ershu/core/security.py</code>: access-token validation and sensitive-value encryption.</li><li><code>core/src/ershu/services/mcp_keys.py</code>: MCP key digests and invalidation behavior.</li><li><code>core/src/ershu/services/repositories/git_url_security.py</code>: remote Git host and address validation.</li><li><code>core/src/ershu/services/repositories/workspaces.py</code>: protocols, credential selection, and temporary credential handling.</li><li><code>core/src/ershu/tools/readonly_repository/workspace.py</code>: local repository trust rules.</li><li><code>api/src/ershu/api_main.py</code>: HTTPS, origin, CSRF, and HSTS processing.</li><li><code>api/src/ershu/api/web_security.py</code>: Cookies and CSRF tokens.</li><li><code>api/src/ershu/api/services/opaque_auth.py</code>: OPAQUE setup initialization, storage, and loading.</li><li><code>api/src/ershu/api/services/repositories/triggers.py</code>: webhook signatures, freshness, and replay protection.</li><li><code>mcp/src/ershu/mcp/runtime_settings.py</code>: MCP production network validation.</li></ul>`,40)])])}const y=t(r,[["render",a]]);export{u as __pageData,y as default};
